/** The fallback prerequisite skills of a skill: [{key, why, opts?}], most basic first ([] when none). Fresh objects. */
export function prereqFallback(key) {
    const i = K.indexOf(String(key || ''));
    return i < 0 || !P[i] ? [] : P[i].map(([j, w, opts]) => (opts ? { key: K[j], why: W[w], opts: JSON.parse(JSON.stringify(opts)) } : { key: K[j], why: W[w] }));
}

export default { prereqFallback };
